import numpy as np
e=eps;t=T
def basis(k, ex):
    g=1-np.exp(-k*t)
    E=[np.ones_like(e),e,e**2,np.log(e),np.sqrt(e)]
    cols=[x for x in E]+[x*g for x in E]
    if ex: cols+= [x/t for x in E[:3]]
    return np.column_stack(cols)
for ex in [0,1]:
  best=None
  for k in np.linspace(0.05,4,80):
    A=basis(k,ex); c,_,_,_=np.linalg.lstsq(A,sigma,rcond=None); r=sigma-A@c
