import numpy as np
from scipy.optimize import least_squares
e=eps;t=T
def model(q):
    g=1-np.exp(-q[0]*t)
    return (q[1]+q[2]*e**q[3]+q[4]*e+q[5]*e**2 + (q[6]+q[7]*e**q[8]+q[9]*e)*g)
best=None
for s in range(40):
    rs=np.random.RandomState(s)
    p0=rs.uniform(-2,2,10); p0[0]=abs(p0[0])+0.2; p0[3]=abs(p0[3])+0.2; p0[8]=abs(p0[8])+0.2
    try:
        r=least_squares(lambda q: model(q)-sigma,p0,max_nfev=3000)
        if best is None or r.cost<best.cost: best=r
    except Exception as ex:
        pass
print("RESULT", float(np.sqrt(np.mean(best.fun**2))), np.round(best.x,5).tolist())
